use vstd::prelude::*;
use vstd::slice::*;
use vstd::vec::*;

verus! {

spec fn is_even(x: i32) -> bool {
    x % 2 == 0
}

spec fn contains_even_values(s: Seq<i32>) -> bool {
    forall|i: int| 0 <= i < s.len() ==> is_even(s[i])
}

spec fn all_even_values_present(input: Seq<i32>, output: Seq<i32>) -> bool {
    forall|i: int| 
        0 <= i < input.len() && is_even(input[i]) ==> 
        exists|j: int| 0 <= j < output.len() && output[j] == input[i]
}

spec fn all_output_values_from_input(input: Seq<i32>, output: Seq<i32>) -> bool {
    forall|j: int| 
        0 <= j < output.len() ==> 
        exists|i: int| 0 <= i < input.len() && input[i] == output[j] && is_even(input[i])
}

fn remove_odd_numbers(arr: &[i32]) -> (result: Vec<i32>)
    requires
        true,
    ensures
        contains_even_values(result@),
        all_even_values_present(arr@, result@),
        all_output_values_from_input(arr@, result@),
{
    let mut result_vec = Vec::new();
    let mut idx: usize = 0;
    
    while idx < arr.len()
        invariant
            0 <= idx <= arr.len(),
            contains_even_values(result_vec@),
            // Every even value in arr[0..idx] appears in result_vec
            forall|i: int| 0 <= i < idx && is_even(arr[i]) ==> 
                exists|j: int| 0 <= j < result_vec.len() && result_vec[j] == arr[i],
            // Every value in result_vec comes from an even value in arr[0..idx]
            forall|j: int| 0 <= j < result_vec.len() ==> 
                exists|i: int| 0 <= i < idx && arr[i] == result_vec[j] && is_even(arr[i]),
        decreases arr.len() - idx,
    {
        let elem = arr[idx];
        if is_even(elem) {
            result_vec.push(elem);
        }
        idx = idx + 1;
    }
    
    result_vec
}

}
